import {object,locate,selectionRoots,uid,clone,isLocked} from '../document/model.js';
import {matrix,multiply,identity,point} from './matrix.js';
export function group(p,ids){const nodes=selectionRoots(p,ids);if(nodes.length<2)throw Error('Select two or more layers to group.');if(nodes.some(n=>isLocked(p,n.id)))throw Error('Unlock the layers before grouping.');const locations=nodes.map(n=>locate(p,n.id));if(!locations.every(l=>l.list===locations[0].list))throw Error('Select layers in the same group.');const list=locations[0].list,index=Math.min(...locations.map(l=>l.index));const g=object('group',{name:'Group',children:list.filter(n=>nodes.includes(n))});for(let i=list.length-1;i>=0;i--)if(nodes.includes(list[i]))list.splice(i,1);list.splice(index,0,g);return g;}
export function ungroup(p,id){const l=locate(p,id),g=l?.node;if(g?.type!=='group')throw Error('Select a group first.');if(g.pathFollow?.enabled)throw Error('Detach the group from its motion path before ungrouping.');if(Object.values(g.tracks).some(t=>t.length)||(g.blocks||[]).some(b=>Object.values(b.tracks||{}).some(t=>t.length))||(g.blockCuts||[]).some(c=>Object.keys(c.values||{}).length))throw Error('Remove the group’s animation tracks and held cuts before ungrouping to preserve child motion.');if(g.opacity!==1)throw Error('Set group opacity to 100% before ungrouping to preserve overlapping artwork.');if(isLocked(p,g.id))throw Error('Unlock the group before ungrouping.');const m=matrix(g);for(const n of g.children){n.prefix=multiply(m,n.prefix||identity());if(n.pathFollow){const origin=point(m,{x:n.pathFollow.originX,y:n.pathFollow.originY});n.pathFollow.originX=origin.x;n.pathFollow.originY=origin.y;}n.visible=n.visible&&g.visible;n.locked=n.locked||g.locked;}l.list.splice(l.index,1,...g.children);return g.children;}
export function duplicate(n){const result=clone(n),idMap=new Map();const renew=o=>{const oldId=o.id;o.id=uid();idMap.set(oldId,o.id);for(const t of Object.values(o.tracks))t.forEach(k=>k.id=uid());for(const b of o.blocks||[]){b.id=uid();for(const keys of Object.values(b.tracks||{}))for(const k of keys)k.id=uid();}o.children.forEach(renew);};renew(result);const relink=o=>{if(o.pathFollow&&idMap.has(o.pathFollow.targetId))o.pathFollow.targetId=idMap.get(o.pathFollow.targetId);o.children.forEach(relink);};relink(result);result.name+=' copy';result.x+=24;result.y+=24;return result;}
